t.script:
(function(){
  var KK = document.getElementById('hl-k').getAttribute('data-k');
  function handleErr(d){
    var m = (d.error && ((d.error.data && d.error.data.message) || d.error.message)) || '';
    if(/session/i.test(m) && /(expir|invalid)/i.test(m)){
      alert('La page était ouverte depuis trop longtemps et la connexion a expiré. Elle va se recharger : merci de refaire votre dernière action.');
      location.reload();
      return;
    }
    alert('Échec : ' + m);
  }
  document.addEventListener('click', function(e){
    var cp = e.target.closest('.hl-copy');
    if(cp){
      var lk = cp.closest('.hl-row').getAttribute('data-link');
      (navigator.clipboard ? navigator.clipboard.writeText(lk) : Promise.reject()).then(function(){
        cp.textContent = '✓ Copié';
        setTimeout(function(){ cp.textContent = '📋 Copier'; }, 1400);
      }).catch(function(){ prompt('Lien personnel :', lk); });
      return;
    }
    var rg = e.target.closest('.hl-regen');
    if(rg){
      var row = rg.closest('.hl-row');
      if(!confirm(row.getAttribute('data-name') + ' : régénérer le lien ? L’ancien ne fonctionnera plus.')){ return; }
      var arr = new Uint8Array(12); crypto.getRandomValues(arr);
      var tok = btoa(String.fromCharCode.apply(null, arr)).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
      fetch('/web/dataset/call_kw',{method:'POST',headers:{'Content-Type':'application/json'},
        body:JSON.stringify({jsonrpc:'2.0',method:'call',params:{model:'ir.actions.server',method:'run',args:[[2020]],kwargs:{context:{active_model:'hr.employee',emp_id:parseInt(row.getAttribute('data-emp')),new_token:tok,hj_k:KK}}}})
      }).then(function(r){return r.json();}).then(function(d){
        if(d.error){ handleErr(d); return; }
        location.reload();
      }).catch(function(){ alert('Échec réseau'); });
    }
  });
})();
